-	if c == nil || c.CoreURL == "" {
+	sel, err := f.Active()
+	if err != nil {
+		return nil, false, err //nolint:wrapcheck // UnknownContextError is already a complete operator message
+	}
+	if sel.Context == nil || sel.Context.CoreURL == "" {
 		return nil, false, nil
 	}
-	return c, true, nil
+	return sel.Context, true, nil
 }

