// Package var so tests can force the whole outcome (see #1773 review thread).
var importLoggedIn = func() bool {
	if os.Getenv(auth.EnvTokenVar) != "" {
		return true
	}
	ctxs, current, err := importListContexts()
	if err != nil || current == "" {
		return false
	}
	for _, c := range ctxs {
		if c.Name == current {
			tok, terr := importTokenForContext(c)
			return terr == nil && tok != ""
		}
	}
	return false
}

